package com.genchat.controller;
import com.genchat.dto.RegisterRequest; import com.genchat.model.User; import com.genchat.service.UserService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/users") public class UserController { private final UserService service; public UserController(UserService service){this.service=service;} @PostMapping("/register") public ResponseEntity<?> register(@Valid @RequestBody RegisterRequest r){try{User u=service.register(r.username(),r.password()); return ResponseEntity.status(HttpStatus.CREATED).body(java.util.Map.of("id",u.getId(),"username",u.getUsername()));}catch(IllegalArgumentException e){return ResponseEntity.badRequest().body(java.util.Map.of("error",e.getMessage()));}} }
